import{bQ as o,aZ as r,aL as n,u as d,G as e,I as p}from"./chunks/framework.C1gZXFVa.js";const b=JSON.parse('{"title":"核心设计","description":"把资产、订单和订单簿作为相互关联的独立对象。","frontmatter":{"title":"核心设计","description":"把资产、订单和订单簿作为相互关联的独立对象。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,现货手册,现货撮合,现货订单,现货结算"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/0704"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/0704"}],["meta",{"property":"og:title","content":"核心设计 · TGEX"}],["meta",{"property":"og:description","content":"把资产、订单和订单簿作为相互关联的独立对象。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"核心设计 · TGEX"}],["meta",{"name":"twitter:description","content":"把资产、订单和订单簿作为相互关联的独立对象。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"核心设计\\",\\"description\\":\\"把资产、订单和订单簿作为相互关联的独立对象。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,现货手册,现货撮合,现货订单,现货结算\\",\\"url\\":\\"https://tgex.net/pages/0704\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/0704\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/0704.md","filePath":"07.现货手册/04.核心设计.md"}'),i={name:"pages/0704.md"};function s(l,t,c,h,g,_){const a=r("Flow");return n(),d("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h1><div class="doc-lead">把资产、订单和订单簿作为相互关联的独立对象。</div><h2 id="account" tabindex="-1">账户与资产 <a class="header-anchor" href="#account" aria-label="Permalink to &quot;账户与资产 {#account}&quot;">​</a></h2><p>买单占用计价币，卖单占用基础币。冻结金额不能只依赖客户端计算，应由服务端结合价格、数量和费用规则确定。未成交资金在订单终止后释放。可用与冻结的口径见<a href="/pages/0601#balances">资产体系与余额设计</a>。</p><p>教学演算中的占用可先按下列方式理解（真实公式以产品规则为准）：</p><table tabindex="0"><thead><tr><th>方向</th><th>占用什么</th><th>简化估算</th></tr></thead><tbody><tr><td>限价买入</td><td>计价币</td><td>约 <code>限价 × 数量</code>，若费用从计价币扣则再加费用缓冲</td></tr><tr><td>限价卖出</td><td>基础币</td><td>约等于委托数量</td></tr><tr><td>市价买入</td><td>计价币</td><td>通常按提交金额或按估价占用，版本差异需核对</td></tr><tr><td>市价卖出</td><td>基础币</td><td>约等于委托数量</td></tr></tbody></table><p>贯穿示例中，用户以 60,000 限价买入 0.01 BTC、先忽略费用时，预占 600 USDT。部分成交 0.006 BTC 后，已支出 360，剩余占用应降到约 240；撤销剩余后再把 240 解冻回可用。</p><h2 id="states" tabindex="-1">订单与状态流转 <a class="header-anchor" href="#states" aria-label="Permalink to &quot;订单与状态流转 {#states}&quot;">​</a></h2>',9)),p(a,{steps:["未成交","部分成交","完全成交 / 已撤销"]}),t[1]||(t[1]=e('<p>这是一条示意路径。未成交也可以直接完全成交或撤销；部分成交后继续成交或撤销。工程状态枚举对应未成交、部分成交、完全成交、已撤销，具体存储值不必暴露给业务读者。</p><p>阅读订单时建议区分三类数量：</p><table tabindex="0"><thead><tr><th>数量概念</th><th>含义</th></tr></thead><tbody><tr><td>原始数量</td><td>用户最初提交的买卖量</td></tr><tr><td>已成交数量</td><td>累计成交，只增不减</td></tr><tr><td>剩余数量</td><td>尚未成交、仍可能挂在簿上或等待终止的部分</td></tr></tbody></table><p>撤单只作用于剩余数量，不能把已成交量改回零。一个委托可以关联多笔成交记录；每笔成交都应能回溯到双方订单、价格、数量与唯一标识。</p><h2 id="orderbook" tabindex="-1">订单簿与撮合机制 <a class="header-anchor" href="#orderbook" aria-label="Permalink to &quot;订单簿与撮合机制 {#orderbook}&quot;">​</a></h2><p>已检查实现中，买方价格队列降序，卖方价格队列升序，撮合优先寻找最优对手价格。买单价格达到卖方价格时可以成交。</p><p>订单簿反映尚未成交的意图，不等于成交历史，也不等于用户的全部历史委托。深度展示通常是把同价位未成交量聚合后的结果，见<a href="/pages/0706">行情与推送</a>。</p><p>以下细节在文档中不固化，需结合具体撮合路径确认后再写入业务说明：</p><ul><li>相同价位的排队规则（例如是否严格时间优先）</li><li>外部成交分支如何写入本地订单与账务</li></ul><p>把「最优价优先」写成业务约束是安全的；把未经核对的同价排队或外部成交语义写成事实，则会误导读者。</p>',10))])}const T=o(i,[["render",s]]);export{b as __pageData,T as default};
